<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch,onBeforeUnmount,nextTick,inject} from 'vue';
import {companionRegions,alignCompanion} from '../../../packages/reference/cross-view';
import ToolIcon from './ToolIcon.vue';
import ZoomViewport from './ZoomViewport.vue';
import {referenceKey} from '../../../packages/reference/resources';
import {penSvg,simplifyPen,type PenPath,type PenPoint,type PenNode} from '../../../packages/reference/pen-path';
import type {Reference,ReferenceRun,Piece} from '../../../packages/schema/index';
import {referenceScene,type ReferenceScene} from './modules/reference-scene';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
const props=defineProps<{reference:Reference;run?:ReferenceRun;language:'zh'|'en';scene?:ReferenceScene;library?:boolean;calibrationDirty?:boolean;focusBox?:string;mode?:'pan'|'select'|'pen'|'lasso'|'calibrate'|'color'}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const emit=defineEmits<{reference:[id:string];accepted:[];pick:[point:PenPoint];mode:[value:'pan'|'select'|'pen'|'lasso'|'calibrate'|'color']}>();
const advanced=inject('advancedMode',ref(false)),scene=computed(()=>props.scene??referenceScene([props.reference])),origin=computed(()=>scene.value.frames.find(f=>f.reference.id===props.reference.id)??{x:0,y:0});
watch(()=>props.mode,value=>{if(value)tool.value=value;});
watch(()=>props.focusBox,value=>{if(value)void nextTick(()=>svg.value?.scrollIntoView({block:'nearest',inline:'nearest'}));});
watch(advanced,value=>{if(!value)subtract.value=false;});
const paths=ref<PenPath[]>([]),active=ref(-1),selected=ref(-1),tool=ref<'pan'|'select'|'pen'|'lasso'|'calibrate'|'color'>(props.mode??'pan'),subtract=ref(false),color=ref('#73c9b6'),expanded=ref(false),svg=ref<SVGSVGElement>(),computing=ref(false),notice=ref(''),count=ref(0),savedId=ref('');
const baseId=ref(''),companionId=ref(''),completion=ref(false),reviewed=ref(false),rotation=ref(0),offsetX=ref(0),offsetY=ref(0),mirror=ref(true),drawing=ref(false);
const regions=computed(()=>store.data.project?.patternLibrary??[]),bases=computed(()=>regions.value.filter(r=>r.referenceId===props.reference.id)),base=computed(()=>bases.value.find(r=>r.piece.id===baseId.value)),companions=computed(()=>base.value?companionRegions(base.value,regions.value):[]);
watch(baseId,()=>{companionId.value=companions.value[0]?.piece.id??'';rotation.value=offsetX.value=offsetY.value=0;});
function complete(){const b=base.value,c=companions.value.find(r=>r.piece.id===companionId.value);if(!b||!c||locked.value)return;try{if(!fromPieces([b.piece,alignCompanion(b.piece,c.piece,mirror.value,rotation.value*Math.PI/180,offsetX.value,offsetY.value)]))return;color.value=b.piece.color;completion.value=true;reviewed.value=false;notice.value=zh.value?'另一视图已按主方向和毫米尺度对齐。请调整节点与孔洞，核对遮挡边界后确认。':localize('Registered the other view without scaling. Adjust nodes and holes, then review occlusion boundaries.');}catch{notice.value=zh.value?'补全参数无效。':localize('Invalid alignment.');}}
const capture=ref<PenPoint[]>([]),generation=ref(0);
const copy=(p=paths.value):PenPath[]=>JSON.parse(JSON.stringify(p));
const current=computed(()=>paths.value[active.value]),node=computed(()=>current.value?.nodes[selected.value]);
const pending=computed(()=>paths.value.some(p=>!p.closed)),ready=computed(()=>paths.value.length>0&&!pending.value&&paths.value.some(p=>!p.subtract)),locked=computed(()=>store.busy||computing.value);
let worker:Worker|undefined,gesture:{id:number;kind:'node'|'in'|'out'|'new'|'lasso';point:PenPoint;node?:PenNode;previous:PenPath[]}|undefined;
const history=useDraftHistory(()=>paths.value,value=>{cancelGesture();paths.value=value;active.value=paths.value.length-1;selected.value=-1;change();},()=>!!svg.value?.getClientRects().length,()=>locked.value);
function step(){history.begin();void nextTick(()=>history.end());generation.value++;count.value=0;reviewed.value=false;}
function change(){generation.value++;count.value=0;reviewed.value=false;}
function cancelCompute(){worker?.terminate();worker=undefined;computing.value=false;generation.value++;}
function cancelGesture(){if(gesture){const id=gesture.id;paths.value=gesture.previous;gesture=undefined;capture.value=[];history.end();if(svg.value?.hasPointerCapture(id))svg.value.releasePointerCapture(id);}drawing.value=false;}
watch(()=>referenceKey(props.reference),()=>{cancelCompute();cancelGesture();history.reset(()=>{paths.value=[];});active.value=selected.value=-1;notice.value='';completion.value=false;reviewed.value=false;baseId.value='';});
onBeforeUnmount(()=>{cancelCompute();cancelGesture();});
function point(e:PointerEvent):PenPoint|undefined{const m=svg.value?.getScreenCTM();if(!m)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse());return {x:Math.max(0,Math.min(props.reference.width,p.x-origin.value.x)),y:Math.max(0,Math.min(props.reference.height,p.y-origin.value.y))};}
async function start(e:PointerEvent){svg.value?.focus({preventScroll:true});if(locked.value||e.button!==0||gesture||tool.value==='pan')return;
 const matrix0=svg.value?.getScreenCTM();if(!matrix0)return;const global=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix0.inverse());
 // Inverting a scaled SVG matrix can put an exact image-edge click a few millionths of a pixel outside.
 const edgeEpsilon=1e-4;const hit=scene.value.frames.find(f=>global.x>=f.x&&global.y>=f.y&&global.x<f.x+f.reference.width&&global.y<f.y+f.reference.height)??scene.value.frames.find(f=>global.x>=f.x-edgeEpsilon&&global.y>=f.y-edgeEpsilon&&global.x<=f.x+f.reference.width+edgeEpsilon&&global.y<=f.y+f.reference.height+edgeEpsilon);if(!hit)return;const pickedAtStart={x:Math.max(0,Math.min(hit.reference.width,global.x-hit.x)),y:Math.max(0,Math.min(hit.reference.height,global.y-hit.y))};
 if(hit.reference.id!==props.reference.id){if(paths.value.length){notice.value=zh.value?'请先确认或清空当前选区，再编辑画面另一位置。':localize('Confirm or clear the current selection before editing another image region.');return;}emit('reference',hit.reference.id);await nextTick();}
 if(['select','calibrate','color'].includes(tool.value)){emit('pick',pickedAtStart);return;}
const p=pickedAtStart;notice.value='';const previous=copy();history.begin();
 if(tool.value==='lasso'){if(paths.value.length>=100){notice.value=zh.value?'路径数量已达上限，请分批处理。':localize('Path limit reached.');return;}capture.value=[p];gesture={id:e.pointerId,kind:'lasso',point:p,previous};}
 else{if(paths.value.reduce((n,p)=>n+p.nodes.length,0)>=10000){notice.value=zh.value?'节点数量已达上限，请简化路径。':localize('Node limit reached.');return;}if(!current.value||current.value.closed){if(paths.value.length>=100)return;paths.value.push({nodes:[],closed:false,subtract:subtract.value});active.value=paths.value.length-1;}if(paths.value.reduce((n,p)=>n+p.nodes.length,0)>=10000){notice.value=zh.value?'节点数量已达上限，请简化路径。':localize('Node limit reached.');return;}current.value!.nodes.push(p);selected.value=current.value!.nodes.length-1;gesture={id:e.pointerId,kind:'new',point:p,previous};}
 drawing.value=true;svg.value?.setPointerCapture(e.pointerId);change();
}
function selectNode(e:PointerEvent,p:number,i:number,kind:'node'|'in'|'out'='node'){if(locked.value||e.button!==0)return;if(kind==='node'&&tool.value==='pen'&&(active.value<0||current.value&&!current.value.closed&&p!==active.value)){start(e);return;}history.begin();active.value=p;selected.value=i;if(!current.value!.closed&&i===0&&current.value!.nodes.length>=3&&kind==='node'){close();return;}const picked=point(e);if(!picked)return;gesture={id:e.pointerId,kind,point:picked,node:JSON.parse(JSON.stringify(node.value)),previous:copy()};drawing.value=true;svg.value?.setPointerCapture(e.pointerId);}
function move(e:PointerEvent){if(!gesture||gesture.id!==e.pointerId)return;const p=point(e);if(!p)return;const g=gesture;
 if(g.kind==='lasso'){const last=capture.value.at(-1)!;if(Math.hypot(last.x-p.x,last.y-p.y)>=1){if(capture.value.length>=12000){cancelGesture();notice.value=zh.value?'路径过长，本次绘制已取消，请分为多条路径。':localize('Path too long; gesture cancelled.');return;}capture.value.push(p);}return;}
 const n=node.value;if(!n)return;
 if(g.kind==='new'){if(Math.hypot(p.x-n.x,p.y-n.y)>2){n.out=p;n.in={x:2*n.x-p.x,y:2*n.y-p.y};}}
 else if(g.kind==='node'){const dx=p.x-g.point.x,dy=p.y-g.point.y;n.x=g.node!.x+dx;n.y=g.node!.y+dy;for(const key of ['in','out'] as const)if(g.node![key])n[key]={x:g.node![key]!.x+dx,y:g.node![key]!.y+dy};}
 else n[g.kind]=p;change();
}
function end(e:PointerEvent){if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;if(g.kind==='lasso'){const nodes=simplifyPen(capture.value,.7);if(nodes.length>=3&&nodes.length+paths.value.reduce((n,p)=>n+p.nodes.length,0)<=10000){paths.value.push({nodes,closed:true,subtract:subtract.value});active.value=paths.value.length-1;selected.value=0;}else notice.value=zh.value?'路径节点过多或不足，本次绘制未应用。':localize('Invalid path size; gesture not applied.');capture.value=[];}history.end();gesture=undefined;drawing.value=false;if(svg.value?.hasPointerCapture(e.pointerId))svg.value.releasePointerCapture(e.pointerId);change();}
function close(){if(locked.value||!current.value||current.value.nodes.length<3)return;step();current.value.closed=true;}
function fresh(){active.value=selected.value=-1;}
function undo(){history.move();}
function redo(){history.move(true);}
function removeNode(){if(locked.value||!node.value)return;step();current.value!.nodes.splice(selected.value,1);if(current.value!.nodes.length<3)current.value!.closed=false;if(!current.value!.nodes.length){paths.value.splice(active.value,1);active.value=-1;}selected.value=-1;}
function removePath(){if(locked.value||active.value<0)return;step();paths.value.splice(active.value,1);active.value=selected.value=-1;}
function clear(){if(locked.value)return;step();completion.value=false;reviewed.value=false;paths.value=[];active.value=selected.value=-1;}
function keyboard(e:KeyboardEvent){if(e.target instanceof Element&&e.target.closest('input,select,textarea,[contenteditable=true]'))return;if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase()))return;if(e.key==='Enter'){e.preventDefault();e.stopPropagation();close();}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();cancelGesture();fresh();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();e.stopPropagation();removeNode();}}
function fromPieces(pieces:Piece[]){const c=props.reference.calibration;if(!c)return false;if(pieces.reduce((n,p)=>n+p.nodes.length+(p.holes??[]).reduce((a,h)=>a+h.length,0),0)>10000||pieces.reduce((n,p)=>n+1+(p.holes?.length??0),0)>100){notice.value=zh.value?'候选路径过多，请分批选择区域；当前草稿未改变。':localize('Too many candidate paths; select fewer regions. Draft unchanged.');return false;}const dx=c.b.x-c.a.x,dy=c.b.y-c.a.y,toPixel=(n:{xMm:number;yMm:number})=>({x:c.a.x+(-dy*n.xMm+dx*n.yMm)/c.distanceMm,y:c.a.y+(dx*n.xMm+dy*n.yMm)/c.distanceMm});step();paths.value=pieces.flatMap(piece=>{const nodes:PenNode[]=piece.nodes.map(toPixel);for(const curve of piece.curves??[]){const a=piece.nodes.findIndex(n=>n.id===curve.startNodeId),b=piece.nodes.findIndex(n=>n.id===curve.endNodeId);if(a>=0&&b>=0){nodes[a].out=toPixel(curve.c1);nodes[b].in=toPixel(curve.c2);}}return [{nodes,closed:true,subtract:false},...(piece.holes??[]).map(h=>({nodes:h.map(toPixel),closed:true,subtract:true}))];});active.value=paths.value.length-1;selected.value=-1;if(pieces[0])color.value=pieces[0].color;return true;}
function load(){if(!locked.value&&props.run?.referenceId===props.reference.id)fromPieces(props.run.pieces??[props.run.piece]);}
function loadSaved(){const p=store.data.project,all=[...(p?.pieces??[]),...(p?.patternLibrary??[]).map(r=>r.piece)];const pieces=all.filter(p=>p.sourceMaskId===savedId.value);if(pieces.length)fromPieces(pieces);else notice.value=zh.value?'此来源没有关联轮廓，请载入当前候选。':localize('No contours for this source; load its candidate.');}
async function candidate(){const p=store.data.project,r=props.reference;if(!p||!r.calibration||props.calibrationDirty||!ready.value||locked.value||gesture||completion.value&&!reviewed.value)return;computing.value=true;notice.value='';const version=generation.value,text=referenceKey(r),snapshot=copy();worker=new Worker(new URL('./mask-worker.ts',import.meta.url),{type:'module'});const own=worker;
 own.onerror=()=>{if(worker===own){notice.value=zh.value?'选区计算失败，请减少节点后重试。':localize('Selection calculation failed.');cancelCompute();}};
 own.onmessage=async({data})=>{if(worker!==own||version!==generation.value)return;own.terminate();worker=undefined;
  try{if(!data.ok){notice.value=data.error;return;}count.value=data.count;if(!data.count){notice.value=zh.value?'选区为空，请检查增加和减去的顺序。':localize('Empty selection.');return;}
   const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));if(version!==generation.value)return;const sourceHash=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
   const accepted=await store.run(()=>window.fpcad.maskReference(p.id,p.revision,r.id,sourceHash,data.mask,color.value,props.library??false));
   if(accepted&&version===generation.value){history.reset(()=>{paths.value=[];});active.value=selected.value=-1;completion.value=reviewed.value=false;emit('accepted');}
   else if(!accepted)notice.value=zh.value?'选区未保存，草稿已保留。请检查错误后重试。':localize('Selection was not saved. Your draft is preserved; resolve the error and retry.');
  }catch{notice.value=zh.value?'选区计算失败，草稿已保留。':localize('Selection calculation failed; your draft is preserved.');}
  finally{if(version===generation.value)computing.value=false;}
 };
 own.postMessage({width:r.width,height:r.height,paths:snapshot});
}
function draftColor(index:number){return `hsl(${(index*137.508+195)%360} 82% 58%)`;}
const radius=computed(()=>Math.max(props.reference.width,props.reference.height)/150);
</script>
<template><section class="mask-editor" :class="{expanded}" @keydown="keyboard">
 <p v-if="['pen','lasso'].includes(tool)">{{zh?'钢笔单击添加节点，按住拖动建立曲线手柄；点击起点或按 Enter 闭合。套索松开后保留可编辑节点。拖动节点与手柄修正，Delete 删除节点。画完不会计算 mask，确认后才在后台计算。':localize('Click for nodes; drag for curve handles. Click the first node or Enter to close. Lasso keeps editable nodes. Move nodes/handles; Delete removes a node. Rasterization runs only after confirmation.')}}</p>
 <details v-if="advanced" class="cross-view-completion"><summary>{{zh?'正背色区补全草稿':localize('Cross-view completion draft')}}</summary><p>{{zh?'选择此视图需要补全的色块，算法按颜色和部位查找另一视图候选，镜像并按主方向对齐。它是待核对的几何推断；可调整角度、偏移以及生成的路径节点。':localize('Choose a source; candidates are ranked by pigment and part. Mirroring and principal-axis registration create an editable inference.')}}</p><fieldset v-show="advanced" class="mask-controls" :disabled="locked"><label>{{zh?'当前视图色块':localize('Base region')}}<select v-model="baseId" aria-label="Completion base"><option value="">—</option><option v-for="r in bases" :key="r.piece.id" :value="r.piece.id">{{r.piece.name}}</option></select></label><label>{{zh?'另一视图候选':localize('Companion region')}}<select v-model="companionId" aria-label="Completion companion"><option v-for="r in companions" :key="r.piece.id" :value="r.piece.id">{{r.piece.name}}</option></select></label><label><input v-model="mirror" type="checkbox">{{zh?'镜像另一视图':localize('Mirror')}}</label><label>角度 °<input v-model.number="rotation" type="number" min="-360" max="360"></label><label>X mm<input v-model.number="offsetX" type="number" min="-100000" max="100000"></label><label>Y mm<input v-model.number="offsetY" type="number" min="-100000" max="100000"></label><button :disabled="!base||!companionId||![rotation,offsetX,offsetY].every(Number.isFinite)" @click="complete">{{zh?'生成可编辑补全路径':localize('Create completion paths')}}</button></fieldset></details>
 <fieldset v-show="['pen','lasso','select'].includes(tool)" class="mask-controls" :disabled="locked"><label v-if="advanced">{{zh?'绘制工具':localize('Tool')}}<select v-model="tool" aria-label="Selection tool" @change="emit('mode',tool)"><option value="select">{{zh?'选择 / 调整节点':localize('Select / edit nodes')}}</option><option value="pen">{{zh?'钢笔路径':localize('Pen path')}}</option><option value="lasso">{{zh?'自由套索':localize('Freehand lasso')}}</option></select></label><label v-if="advanced">{{zh?'选区叠加方式':localize('Selection combination')}}<select v-model="subtract" aria-label="Selection operation"><option :value="false">{{zh?'增加选区':localize('Add selection')}}</option><option :value="true">{{zh?'减去选区 / 孔洞':localize('Subtract / hole')}}</option></select></label><label>{{zh?'花纹颜色':localize('Marking color')}}<input v-model="color" type="color"></label><select v-if="advanced" v-model="savedId" aria-label="Saved mask source"><option value="">{{zh?'已保存来源':localize('Saved source')}}</option><option v-for="m in store.data.project?.maskSources?.filter(m=>m.referenceId===reference.id)" :key="m.id" :value="m.id">{{m.id.slice(0,8)}}</option></select></fieldset>
 <ZoomViewport hide-interaction-tools :focus-box="focusBox" :drawing="drawing" :interaction="tool==='pan'?'pan':'edit'" @interaction="tool=$event==='pan'?'pan':'select';emit('mode',tool)" :view-box="`0 0 ${scene.width} ${scene.height}`" label="Pen selection" :language="language" ><template #rail><fieldset v-show="['pen','lasso','select'].includes(tool)" class="mask-draft-tools" :disabled="locked"><button :aria-label="zh?(expanded?'收起选区编辑':'放大选区编辑'):(expanded?'Collapse':'Expand')" :title="zh?(expanded?'收起选区编辑':'放大选区编辑'):(expanded?'Collapse':'Expand')" @click="expanded=!expanded"><ToolIcon :name="expanded?'collapse':'expand'"/></button><button v-if="paths.length" @click="fresh" :aria-label="zh?'新增路径':localize('New path')" :title="zh?'新增路径':localize('New path')"><ToolIcon name="add"/></button><button v-if="current&&!current.closed" :disabled="!current||current.closed||current.nodes.length<3" @click="close" :aria-label="zh?'闭合路径':localize('Close path')" :title="zh?'闭合路径':localize('Close path')"><ToolIcon name="close"/></button><button v-if="node" :disabled="!node" @click="removeNode" :aria-label="zh?'删除节点':localize('Delete node')" :title="zh?'删除节点':localize('Delete node')"><ToolIcon name="node"/></button><button v-if="active>=0" :disabled="active<0" @click="removePath" :aria-label="zh?'删除路径':localize('Delete path')" :title="zh?'删除路径':localize('Delete path')"><ToolIcon name="delete"/></button><button v-if="history.canUndo.value" :disabled="!history.canUndo.value" @click="undo" :aria-label="zh?'撤销选区':localize('Undo selection')" :title="zh?'撤销选区':localize('Undo selection')"><ToolIcon name="undo"/></button><button v-if="advanced&&history.canRedo.value" :disabled="!history.canRedo.value" @click="redo" :aria-label="zh?'重做选区':localize('Redo selection')" :title="zh?'重做选区':localize('Redo selection')"><ToolIcon name="redo"/></button><button v-if="paths.length" @click="clear" :aria-label="zh?'清空草稿':localize('Clear draft')" :title="zh?'清空草稿':localize('Clear draft')"><ToolIcon name="clear"/></button><button v-if="advanced" :disabled="!savedId" @click="loadSaved" :aria-label="zh?'载入已保存路径':localize('Load saved paths')" :title="zh?'载入已保存路径':localize('Load saved paths')"><ToolIcon name="import"/></button><button v-if="run?.referenceId===reference.id" :disabled="run?.referenceId!==reference.id" @click="load" :aria-label="zh?'载入候选为可编辑路径':localize('Edit candidate paths')" :title="zh?'载入候选为可编辑路径':localize('Edit candidate paths')"><ToolIcon name="pen"/></button></fieldset></template><template #default="{viewBox}"><svg ref="svg" class="mask-view" :viewBox="viewBox" aria-label="Pen selection canvas" tabindex="0" @pointerdown.prevent="start" @pointermove="move" @pointerup="end" @pointercancel="cancelGesture"><image v-if="scene.png" :href="scene.png" :width="scene.width" :height="scene.height"/><template v-else><image v-for="f in scene.frames" :key="f.reference.id" :href="f.reference.png" :x="f.x" :y="f.y" :width="f.reference.width" :height="f.reference.height"/></template><slot name="overlay"/><g :transform="`translate(${origin.x} ${origin.y})`">
  <g v-for="(path,pi) in paths" :key="pi"><path :d="penSvg(path)" :fill="path.closed?draftColor(pi):'none'" fill-opacity=".12" :stroke="draftColor(pi)" :stroke-dasharray="path.subtract?'5 3':undefined" stroke-width="1.5" vector-effect="non-scaling-stroke" pointer-events="none" class="selection-overlay draft-path" :data-path-index="pi"/>
   <g v-for="(n,ni) in path.nodes" :key="ni"><template v-if="pi===active&&ni===selected"><g v-for="key in (['in','out'] as const)" :key="key"><template v-if="n[key]"><line :x1="n.x" :y1="n.y" :x2="n[key]!.x" :y2="n[key]!.y" :stroke="draftColor(pi)" vector-effect="non-scaling-stroke"/><rect class="pen-handle" :x="n[key]!.x-radius*.6" :y="n[key]!.y-radius*.6" :width="radius*1.2" :height="radius*1.2" fill="white" :stroke="draftColor(pi)" @pointerdown.stop.prevent="selectNode($event,pi,ni,key)"/></template></g></template><circle class="pen-node" :cx="n.x" :cy="n.y" :r="radius*.7" :fill="pi===active&&ni===selected?draftColor(pi):'white'" :stroke="draftColor(pi)" vector-effect="non-scaling-stroke" @pointerdown.stop.prevent="selectNode($event,pi,ni)"/></g>
  </g><polyline v-if="capture.length" :points="capture.map(p=>`${p.x},${p.y}`).join(' ')" fill="none" stroke="var(--accent)" vector-effect="non-scaling-stroke"/></g></svg></template></ZoomViewport>
 <label v-if="completion" class="check-label"><input v-model="reviewed" type="checkbox" :disabled="locked">{{zh?'已核对补全路径、孔洞和遮挡边界；接受此推断':localize('I reviewed inferred paths, holes and occlusion boundaries')}}</label><div v-if="paths.length" class="mask-controls"><strong>{{paths.length}} {{zh?'条路径':localize('paths')}} · {{paths.reduce((n,p)=>n+p.nodes.length,0)}} {{zh?'个节点':localize('nodes')}}</strong><span v-if="pending" class="warning">{{zh?'存在未闭合路径':localize('Close all paths first')}}</span><button class="primary" :disabled="locked||!ready||!reference.calibration||calibrationDirty||completion&&!reviewed" @click="candidate">{{zh?(library?'确认选区并加入花纹库':'确认选区并加入纸样'):(library?'Confirm selection and add to library':'Confirm selection and add to pattern')}}</button><button v-if="computing&&!store.busy" @click="cancelCompute">{{zh?'取消计算':localize('Cancel calculation')}}</button><span v-if="count">{{count}} px</span><span v-if="!reference.calibration" class="warning">{{zh?'请先保存比例标定':localize('Save calibration first')}}</span></div><p v-if="notice" role="status">{{notice}}</p><small v-if="paths.length">{{zh?'不同颜色区分草稿路径，虚线表示减去选区。确认后计算选区并保存到花纹库；失败时草稿会保留。':localize('Colors distinguish draft paths; dashed paths subtract. Confirm to calculate and save. Failed calculations preserve the draft.')}}</small>
</section></template>
<style scoped>.mask-editor{border-top:1px solid var(--border);margin:16px 0;padding-top:12px}summary{cursor:pointer;font-weight:600}.mask-controls{border:0;margin:12px 0;padding:0;display:flex;gap:10px;flex-wrap:wrap;align-items:end}.mask-draft-tools{border:0;margin:0;padding:0;display:flex;flex-direction:column;gap:4px}.mask-draft-tools button{padding:7px;display:grid;place-items:center}.mask-controls select{width:160px}.mask-controls input{max-width:100px}.mask-view{width:100%;height:clamp(400px,60vh,780px);display:block;background:var(--canvas);touch-action:none;cursor:crosshair}.pen-node{cursor:move}p{line-height:1.7}small{color:var(--text-muted)}.expanded{position:fixed;inset:40px 20px;z-index:40;background:var(--panel);border:1px solid var(--border);border-radius:4px;padding:18px;overflow:auto}.expanded .mask-view{height:calc(100vh - 300px);min-height:300px}</style>
